// ✅ Fixed: Wait until client has mounted
function Greeting() {
  const [user, setUser] = useState<string | null>(null);
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
    setUser(localStorage.getItem('user'));
  }, []);
  if (!mounted) return <div>Welcome Guest</div>;
  return <div>Welcome {user || 'Guest'}</div>;
}

